void process_api_commands() {
  volatile uint32_t *cmd_ptr =
      reinterpret_cast<volatile uint32_t *>(CMD_OFFSET);
  volatile uint8_t *status_ptr =
      reinterpret_cast<volatile uint8_t *>(STATUS_OFFSET);
  volatile uint8_t *payload = reinterpret_cast<volatile uint8_t *>(CMD_DATA);

  if (*status_ptr != STATUS_PENDING || *cmd_ptr == CMD_NONE) {
    return;
  }

  uint32_t cmd = *cmd_ptr;
  const uint32_t handler_count = static_cast<uint32_t>(
      sizeof(command_handlers) / sizeof(command_handlers[0]));
  if (cmd >= handler_count || command_handlers[cmd] == nullptr) {
    update_status(STATUS_OFFSET, STATUS_DONE);
    *cmd_ptr = CMD_NONE;
    return;
  }

  command_handlers[cmd](cmd, payload, cmd_ptr, status_ptr);
}
